sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from support import run_cli

T = "id,city,kind\n1,Leeds,a\n2,York,b\n3,Leeds,a\n4,leeds,a\n5,York,c\n6,Leeds,b\n"
F = {"t.csv": T}


def ids(*argv, files=None):
    rc, out, err = run_cli("--format", "csv", "dedupe", *argv, files=files or F)
    assert rc == 0, (rc, err)
    return [line.split(",")[0] for line in out.splitlines()[1:]]


class DedupeTests(unittest.TestCase):
    def test_keep_and_keys(self):
        for argv, want in [
            (["t.csv", "city"], ["1", "2", "4"]),
            (["t.csv", "city", "--keep", "first"], ["1", "2", "4"]),
            (["t.csv", "city", "--keep=last"], ["4", "5", "6"]),
            (["--keep", "last", "t.csv", "city", "kind"], ["2", "3", "4", "5", "6"]),
            (["t.csv", "city", "kind"], ["1", "2", "4", "5", "6"]),
            (["t.csv", "kind", "city", "kind"], ["1", "2", "4", "5", "6"]),
            (["t.csv", "id"], ["1", "2", "3", "4", "5", "6"]),
        ]:
            with self.subTest(argv):
                self.assertEqual(ids(*argv), want)

    def test_exact_text_and_edges(self):
        f = {"t.csv": "k,v\n1,x\n01,y\n1.0,z\n a,w\na,u\n1,t\n"}
        self.assertEqual(ids("t.csv", "k", files=f), ["1", "01", "1.0", " a", "a"])
        self.assertEqual(ids("t.csv", "k", "--keep=last", files=f), ["01", "1.0", " a", "a", "1"])
        self.assertEqual(run_cli("--format=csv", "dedupe", "t.csv", "k", files={"t.csv": "k,v\n"}), (0, "k,v\n", ""))

    def test_formats(self):
        f = {"t.csv": "k,v\na,1\nb,2\na,3\n"}
        for fmt, out in [("text", "k  v\nb  2\na  3\n"), ("csv", "k,v\nb,2\na,3\n"),
                         ("json", '[{"k": "b", "v": "2"}, {"k": "a", "v": "3"}]\n')]:

